			Title = options.Title or "Confirm action", Content = options.Content,
			Buttons = {
				{ Text = options.CancelText or "Cancel" },
				{ Text = options.ConfirmText or "Confirm", Style = options.Danger and "Danger" or "Primary", Callback = options.Callback },
			},
